class Solution {
  public int minFlips(int[][] grid) {
    int m = grid.length, n = grid[0].length, flips = 0;
    // four mirrored cells must be equal: flip the minority
    for (int i = 0; i < m / 2; i++) {
      for (int j = 0; j < n / 2; j++) {
        int ones =
            grid[i][j] + grid[i][n - 1 - j] + grid[m - 1 - i][j] + grid[m - 1 - i][n - 1 - j];
        flips += Math.min(ones, 4 - ones);
      }
    }
    int mismatched = 0, matchedOnes = 0; // pairs on the middle row / column
    if (m % 2 == 1) {
      for (int j = 0; j < n / 2; j++) {
        int a = grid[m / 2][j], b = grid[m / 2][n - 1 - j];
        if (a != b) mismatched++;
        else if (a == 1) matchedOnes++;
      }
    }
    if (n % 2 == 1) {
      for (int i = 0; i < m / 2; i++) {
        int a = grid[i][n / 2], b = grid[m - 1 - i][n / 2];
        if (a != b) mismatched++;
        else if (a == 1) matchedOnes++;
      }
    }
    if (m % 2 == 1 && n % 2 == 1 && grid[m / 2][n / 2] == 1)
      flips++; // a lone centre cell must be 0
    flips += mismatched;
    // every pair of ones adds 2; the total must be divisible by 4
    if (mismatched == 0 && matchedOnes % 2 == 1) flips += 2;
    return flips;
  }
}
